import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import ScarewareSimulation from './components/ScarewareSimulation';
import EducationalInfo from './components/EducationalInfo';
import WarningBanner from './components/WarningBanner';
import EscapeGuide from './components/EscapeGuide';
import SimulationControls from './components/SimulationControls';

interface SimulationState {
  isActive: boolean;
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape';
  showEducationalInfo: boolean;
}

// Main App component that handles routing
const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

// Inner component that handles the actual app logic
const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const [simulationState, setSimulationState] = useState<SimulationState>({
    isActive: false,
    currentPhase: 'norton',
    showEducationalInfo: false,
  });

  // Sync URL with current phase
  useEffect(() => {
    const path = location.pathname.substring(1); // Remove leading slash
    if (path && path !== '') {
      const validPhases = ['norton', 'microsoft', 'google', 'malwarebytes', 'generic', 'advanced', 'extreme', 'escape'];
      if (validPhases.includes(path)) {
        setSimulationState(prev => ({
          ...prev,
          isActive: true,
          currentPhase: path as SimulationState['currentPhase']
        }));
      }
    }
  }, [location.pathname]);

  const startSimulation = () => {
    setSimulationState(prev => ({
      ...prev,
      isActive: true,
      currentPhase: 'norton'
    }));
    navigate('/norton');
  };

  const stopSimulation = () => {
    setSimulationState({
      isActive: false,
      currentPhase: 'norton',
      showEducationalInfo: false,
    });
    navigate('/');
  };

  const showEducationalInfo = () => {
    setSimulationState(prev => ({
      ...prev,
      showEducationalInfo: true
    }));
  };

  const hideEducationalInfo = () => {
    setSimulationState(prev => ({
      ...prev,
      showEducationalInfo: false
    }));
  };

  const advancePhase = (phase: SimulationState['currentPhase']) => {
    setSimulationState(prev => ({
      ...prev,
      currentPhase: phase
    }));
    navigate(`/${phase}`);
  };

  const resetSimulation = () => {
    // Real scareware technique: Full page reload to completely clear all hijacking
    console.log('🔄 Resetting simulation with full page reload...'); // Debug log
    window.location.reload();
  };

  return (
    <div className="simulation-container">
      <WarningBanner />

      <Routes>
        {/* Home route - landing page */}
        <Route path="/" element={
          <div className="simulation-content">
            <h1>🚨 Scareware Simulation - Educational Tool</h1>

            <div className="escape-info">
              <h3>⚠️ Important: This is a Safe Educational Simulation</h3>
              <p>
                This website demonstrates common scareware techniques in a controlled, 
                educational environment. You are completely safe and can exit at any time.
              </p>
            </div>

            <div style={{ margin: '2rem 0' }}>
              <h2>What You'll Learn</h2>
              <ul style={{ margin: '1rem 0', paddingLeft: '2rem' }}>
                <li>How scareware creates fake security alerts</li>
                <li>Common browser hijacking techniques</li>
                <li>How to identify and avoid real threats</li>
                <li>Proper escape procedures for real situations</li>
                <li>What to do if you encounter actual scareware</li>
              </ul>
            </div>

            <div style={{ margin: '2rem 0' }}>
              <button 
                className="button button-primary" 
                onClick={startSimulation}
                style={{ marginRight: '1rem' }}
              >
                Start Simulation
              </button>
              <button 
                className="button button-success" 
                onClick={showEducationalInfo}
              >
                Learn More First
              </button>
            </div>

            <div style={{ 
              background: '#f8f9fa', 
              padding: '1.5rem', 
              borderRadius: '8px',
              marginTop: '2rem'
            }}>
              <h3>Safety Features</h3>
              <ul style={{ margin: '1rem 0', paddingLeft: '2rem' }}>
                <li>✅ Clear "SIMULATION" indicators throughout</li>
                <li>✅ Easy exit buttons always available</li>
                <li>✅ Educational information at every step</li>
                <li>✅ No actual system changes or downloads</li>
                <li>✅ Safe for all ages and experience levels</li>
              </ul>
            </div>
          </div>
        } />

        {/* Scareware phase routes */}
        <Route path="/norton" element={
          <ScarewareSimulation
            currentPhase="norton"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/microsoft" element={
          <ScarewareSimulation
            currentPhase="microsoft"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/google" element={
          <ScarewareSimulation
            currentPhase="google"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/malwarebytes" element={
          <ScarewareSimulation
            currentPhase="malwarebytes"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/generic" element={
          <ScarewareSimulation
            currentPhase="generic"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/advanced" element={
          <ScarewareSimulation
            currentPhase="advanced"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/extreme" element={
          <ScarewareSimulation
            currentPhase="extreme"
            onAdvancePhase={advancePhase}
            onStop={stopSimulation}
            onShowEducationalInfo={showEducationalInfo}
          />
        } />

        <Route path="/escape" element={
          <EscapeGuide 
            onRestart={() => advancePhase('norton')}
            onStop={stopSimulation}
            onLearnMore={showEducationalInfo}
          />
        } />

        {/* Catch all route - redirect to home */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>

      {/* Floating Simulation Controls - Always visible during simulation */}
      {simulationState.isActive && (
        <SimulationControls
          currentPhase={simulationState.currentPhase}
          onAdvancePhase={advancePhase}
          onLearnMore={showEducationalInfo}
          onReset={resetSimulation}
        />
      )}

      {simulationState.showEducationalInfo && (
        <EducationalInfo onClose={hideEducationalInfo} />
      )}
    </div>
  );
};

export default App;
